using System.Text;using System.Text.Json;namespace QuantForge.Core;public sealed class AndroidResearchLaunchDraftFileStore{private readonly string _path;public AndroidResearchLaunchDraftFileStore(string path)=>_path=Path.GetFullPath(path);public void Save(AndroidResearchLaunchDraft value){if(value.CanSubmitOrders||!value.Ready)throw new InvalidOperationException("Only ready research-only drafts may persist.");Directory.CreateDirectory(Path.GetDirectoryName(_path)!);File.WriteAllText(_path,JsonSerializer.Serialize(value,new JsonSerializerOptions{WriteIndented=true}),new UTF8Encoding(false));}public AndroidResearchLaunchDraft Load(){var v=JsonSerializer.Deserialize<AndroidResearchLaunchDraft>(File.ReadAllText(_path))??throw new InvalidOperationException("Launch draft JSON is invalid.");if(v.CanSubmitOrders||!v.Ready)throw new InvalidOperationException("Persisted launch draft is invalid.");return v;}}
